CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, name TEXT NOT NULL, password TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS users_name_unique ON users(lower(name));
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), csrf TEXT NOT NULL, expires BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS colonies(user_id TEXT PRIMARY KEY REFERENCES users(id), state TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS world(id INTEGER PRIMARY KEY CHECK(id=1), state TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS commands(user_id TEXT NOT NULL REFERENCES users(id), token TEXT NOT NULL, signature TEXT NOT NULL, PRIMARY KEY(user_id, token));
CREATE TABLE IF NOT EXISTS ledger(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), timestamp BIGINT NOT NULL, action TEXT NOT NULL, before_state TEXT NOT NULL, after_state TEXT NOT NULL);
CREATE OR REPLACE FUNCTION fur_immutable() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable audit record'; END; $$;
DROP TRIGGER IF EXISTS ledger_immutable ON ledger;
CREATE TRIGGER ledger_immutable BEFORE UPDATE OR DELETE ON ledger FOR EACH ROW EXECUTE FUNCTION fur_immutable();
